package main

import (
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"
	"time"

	"github.com/gorilla/websocket"
)

var upgrader = websocket.Upgrader{
	ReadBufferSize:  1024,
	WriteBufferSize: 1024,
	CheckOrigin: func(r *http.Request) bool {
		return true
	},
}

var logFile *os.File

func init() {
	var err error
	logPath := os.Getenv("WS_LOG_PATH")
	if logPath == "" {
		logPath = "/var/log/websocket-service/messages.log"
	}
	logFile, err = os.OpenFile(logPath, os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0644)
	if err != nil {
		log.Fatalf("Failed to open log file: %v", err)
	}
}

func writeLogEntry(username, action, payload string) {
	timestamp := time.Now().UTC().Format(time.RFC3339)
	// Log format: timestamp | username | action | payload
	entry := fmt.Sprintf("%s | %s | %s | %s\n", timestamp, username, action, payload)
	logFile.WriteString(entry)
}

func handleWebSocket(w http.ResponseWriter, r *http.Request) {
	username := r.URL.Query().Get("user")
	if username == "" {
		username = "anonymous"
	}

	conn, err := upgrader.Upgrade(w, r, nil)
	if err != nil {
		log.Printf("Upgrade error: %v", err)
		return
	}
	defer conn.Close()

	writeLogEntry(username, "CONNECTED", r.RemoteAddr)

	for {
		msgType, message, err := conn.ReadMessage()
		if err != nil {
			writeLogEntry(username, "DISCONNECTED", err.Error())
			break
		}

		if msgType == websocket.TextMessage {
			payload := string(message)

			// Basic input length check
			if len(payload) > 4096 {
				conn.WriteMessage(websocket.TextMessage, []byte(`{"error":"message too long"}`))
				continue
			}

			// Process commands
			if strings.HasPrefix(payload, "/nick ") {
				newNick := strings.TrimPrefix(payload, "/nick ")
				writeLogEntry(username, "NICK_CHANGE", newNick)
				username = newNick
				conn.WriteMessage(websocket.TextMessage, []byte(fmt.Sprintf(`{"nick":"%s"}`, newNick)))
			} else if strings.HasPrefix(payload, "/status ") {
				status := strings.TrimPrefix(payload, "/status ")
				writeLogEntry(username, "STATUS_UPDATE", status)
				conn.WriteMessage(websocket.TextMessage, []byte(fmt.Sprintf(`{"status":"%s"}`, status)))
			} else {
				writeLogEntry(username, "MESSAGE", payload)
				// Echo back to sender
				response := fmt.Sprintf(`{"from":"%s","msg":"%s"}`, username, payload)
				conn.WriteMessage(websocket.TextMessage, []byte(response))
			}
		}
	}
}

func handleHealth(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusOK)
	w.Write([]byte(`{"status":"healthy"}`))
}

func main() {
	http.HandleFunc("/ws", handleWebSocket)
	http.HandleFunc("/health", handleHealth)

	port := os.Getenv("WS_PORT")
	if port == "" {
		port = "8080"
	}

	log.Printf("WebSocket service starting on :%s", port)
	if err := http.ListenAndServe(":"+port, nil); err != nil {
		log.Fatalf("Server failed: %v", err)
	}
}
